"""C229126 target selection for a same-direction left pass.

The numeric targets are construction controls. They do not define the law's
safe distance or safely clear language.
"""

TARGETS = {
    "left_pass_wide": (1.5, 1.0),
    "left_pass_narrow": (0.5, 1.0),
    "return_before_clear": (1.0, -0.5),
    "return_after_clear": (1.0, 1.5),
}


def target(case_suffix, *, passed_abreast, body_clearance_m,
           right_lane_id, left_lane_id):
    if case_suffix not in TARGETS:
        raise ValueError("Unknown exact C229126 overtake case")
    if right_lane_id == left_lane_id or not all(
            isinstance(value, int) for value in (right_lane_id, left_lane_id)):
        raise ValueError("Distinct mapped travel lanes required")
    left_gap, return_clearance = TARGETS[case_suffix]
    if passed_abreast and body_clearance_m >= return_clearance:
        return {"phase": "return_right", "lane_id": right_lane_id,
                "target_left_gap_m": None,
                "requested_return_clearance_m": return_clearance}
    return {"phase": "pass_left", "lane_id": left_lane_id,
            "target_left_gap_m": left_gap,
            "requested_return_clearance_m": return_clearance}

"""Four synchronized original RGB source streams for C229126 passing cases."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-9, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown overtake source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior exposure camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original overtake camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Overtake source encoder failed")


class OvertakeCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named overtake source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original overtake camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original overtake camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Overtake source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original overtake source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original overtake camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

"""CARLA-lazy exact overtaking actor placement for the C229126 cell."""

from overtake_route import select_overtake_route


def build_scene(world, *, blueprint_id='vehicle.tesla.model3',
                other_index=8, route_steps=70):
    if not 4 <= other_index < route_steps:
        raise ValueError('Overtaken actor must start ahead on selected route')
    route = select_overtake_route(world.get_map(), steps=route_steps)
    blueprints = world.get_blueprint_library()
    blueprint = blueprints.find(blueprint_id)
    if blueprint is None:
        raise ValueError('Native overtaking vehicle blueprint unavailable')
    actors = []
    try:
        other = world.try_spawn_actor(blueprint, route['right'][other_index].transform)
        if other is None:
            raise ValueError('Native overtaken actor spawn failed')
        actors.append(other)
        ego = world.try_spawn_actor(blueprint, route['right'][0].transform)
        if ego is None:
            raise ValueError('Native overtaking subject spawn failed')
        actors.append(ego)
        if ego.id == other.id:
            raise ValueError('Native overtaking actor identity collided')
        return {'route': route, 'ego': ego, 'other': other, 'actors': actors,
                'spawn_indices': {'ego': 0, 'other': other_index}}
    except BaseException:
        for actor in reversed(actors):
            actor.destroy()
        raise


def destroy_scene(scene):
    for actor in reversed(scene['actors']):
        actor.destroy()

